import heapq
class Solution:
    def minCost(self, nums, queries):
        n = len(nums)
        closest = []
        for x in range(n):
            best, bc = -1, float('inf')
            for y in (x - 1, x + 1):
                if 0 <= y < n:
                    d = abs(nums[x] - nums[y])
                    if d < bc or (d == bc and y < best):
                        best, bc = y, d
            closest.append(best)
        res = []
        for l, r in queries:
            dist = [float('inf')] * n
            dist[l] = 0
            pq = [(0, l)]
            while pq:
                d, u = heapq.heappop(pq)
                if u == r:
                    break
                if d > dist[u]:
                    continue
                cand = [(closest[u], 1)] + [(v, abs(nums[u] - nums[v])) for v in range(n) if v != u]
                for v, w in cand:
                    nd = d + w
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(pq, (nd, v))
            res.append(dist[r])
        return res

