class Solution {
public:
    vector<long long> minCost(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> closest(n);
        for (int x = 0; x < n; x++) {
            int best = -1; long long bc = LLONG_MAX;
            for (int y : {x - 1, x + 1}) {
                if (y >= 0 && y < n) {
                    long long d = abs((long long)nums[x] - nums[y]);
                    if (d < bc || (d == bc && y < best)) { best = y; bc = d; }
                }
            }
            closest[x] = best;
        }
        vector<long long> res;
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            vector<long long> dist(n, LLONG_MAX);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
            dist[l] = 0; pq.push({0, l});
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                if (u == r) break;
                auto relax = [&](int v, long long w) {
                    if (d + w < dist[v]) { dist[v] = d + w; pq.push({d + w, v}); }
                };
                relax(closest[u], 1);
                for (int v = 0; v < n; v++)
                    if (v != u) relax(v, abs((long long)nums[u] - nums[v]));
            }
            res.push_back(dist[r]);
        }
        return res;
    }
};

