class Solution {
    public long[] minCost(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] closest = new int[n];
        for (int x = 0; x < n; x++) {
            int best = -1; long bc = Long.MAX_VALUE;
            for (int y : new int[]{x - 1, x + 1}) {
                if (y >= 0 && y < n) {
                    long d = Math.abs((long) nums[x] - nums[y]);
                    if (d < bc || (d == bc && y < best)) { best = y; bc = d; }
                }
            }
            closest[x] = best;
        }
        long[] res = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            long[] dist = new long[n];
            Arrays.fill(dist, Long.MAX_VALUE);
            PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
            dist[l] = 0; pq.add(new long[]{0, l});
            while (!pq.isEmpty()) {
                long[] top = pq.poll();
                long d = top[0]; int u = (int) top[1];
                if (d > dist[u]) continue;
                if (u == r) break;
                if (d + 1 < dist[closest[u]]) { dist[closest[u]] = d + 1; pq.add(new long[]{d + 1, closest[u]}); }
                for (int v = 0; v < n; v++) {
                    if (v == u) continue;
                    long w = Math.abs((long) nums[u] - nums[v]);
                    if (d + w < dist[v]) { dist[v] = d + w; pq.add(new long[]{d + w, v}); }
                }
            }
            res[qi] = dist[r];
        }
        return res;
    }
}

