        let best = -1, bc = Infinity;
        for (const y of [x - 1, x + 1]) {
            if (y >= 0 && y < n) {
                const d = Math.abs(nums[x] - nums[y]);
                if (d < bc || (d === bc && y < best)) { best = y; bc = d; }
            }
        }
        closest.push(best);
    }
    return queries.map(([l, r]) => {
        const dist = Array(n).fill(Infinity);
        dist[l] = 0;
        const pq = [[0, l]];
        while (pq.length) {
            let bi = 0;
            for (let i = 1; i < pq.length; i++) if (pq[i][0] < pq[bi][0]) bi = i;
            const [d, u] = pq.splice(bi, 1)[0];
            if (u === r) break;
            if (d > dist[u]) continue;
            const relax = (v, w) => {
                if (d + w < dist[v]) { dist[v] = d + w; pq.push([d + w, v]); }
            };
            relax(closest[u], 1);
            for (let v = 0; v < n; v++) if (v !== u) relax(v, Math.abs(nums[u] - nums[v]));
        }
        return dist[r];
    });
};

