class Solution:
    def minCostBetweenIndices(self, nums, queries):
        n = len(nums)
        closest = [0] * n
        for x in range(n):
            best, bc = -1, float('inf')
            for y in (x - 1, x + 1):
                if 0 <= y < n:
                    d = abs(nums[x] - nums[y])
                    if d < bc or (d == bc and y < best):
                        best, bc = y, d
            closest[x] = best
        pr = [0] * n
        pl = [0] * n
        for i in range(n - 1):
            gap = nums[i + 1] - nums[i]
            rc = 1 if closest[i] == i + 1 else gap
            lc = 1 if closest[i + 1] == i else gap
            pr[i + 1] = pr[i] + rc
            pl[i + 1] = pl[i] + lc
        ans = []
        for l, r in queries:
            if l < r:
                ans.append(pr[r] - pr[l])
            else:
                ans.append(pl[l] - pl[r])
        return ans

